const donationDialog=document.querySelector('#donation-dialog');
const contentDialog=document.querySelector('#content-dialog');
let amount=100,frequency='One-time';
function openDonation(){contentDialog.close();document.querySelector('#gift-feedback').textContent='';donationDialog.showModal()}
document.querySelectorAll('[data-donate]').forEach(b=>b.addEventListener('click',openDonation));
document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
function updateSummary(){document.querySelector('#selection-summary').textContent=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(amount)+' · '+frequency;document.querySelector('#gift-feedback').textContent=''}
document.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>{amount=Number(b.dataset.amount);document.querySelector('#custom-amount').value='';document.querySelectorAll('[data-amount]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});updateSummary()}));
document.querySelectorAll('[data-frequency]').forEach(b=>b.addEventListener('click',()=>{frequency=b.dataset.frequency;document.querySelectorAll('[data-frequency]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});updateSummary()}));
document.querySelector('#custom-amount').addEventListener('input',e=>{amount=Number(e.target.value);document.querySelectorAll('[data-amount]').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false')});updateSummary()});

const programmes={learning:{title:'A strong beginning.',body:'Children need consistent access to learning and the resources that make it possible. Our education priority explores scholarships, learning materials and community learning opportunities.',items:['Publish programme locations and eligibility.','Define selection, safeguarding and delivery arrangements.','Report resources delivered and learning-related outcomes.']},livelihoods:{title:'A way forward.',body:'Our youth priority focuses on useful skills, access to tools and practical experience that can support economic independence. Employment or earnings will not be guaranteed without evidence and committed opportunities.',items:['Define practical training and mentoring.','Identify partners and pathways into paid work.','Measure participation and follow-up livelihood outcomes.']},wellbeing:{title:'A stronger foundation.',body:'Community wellbeing means helping households build stability and access practical support. Specific interventions will be shaped with local partners and relevant expertise.',items:['Identify a defined community need.','Publish eligibility, partners and a delivery budget.','Track delivery and appropriate recovery or wellbeing outcomes.']}};
function showContent(kicker,title,body,action=true){document.querySelector('#content-kicker').textContent=kicker;document.querySelector('#content-title').textContent=title;document.querySelector('#content-body').innerHTML=body;document.querySelector('#content-action').hidden=!action;contentDialog.showModal()}
document.querySelectorAll('[data-programme]').forEach(b=>b.addEventListener('click',()=>{const p=programmes[b.dataset.programme];showContent('OUR PROGRAMME PRIORITIES',p.title,`<p>${p.body}</p><p><strong>Programme details are in preparation.</strong> Before fundraising for a specific intervention, AfriRise will:</p><ul>${p.items.map(x=>`<li>${x}</li>`).join('')}</ul><p>No location, participant count, delivery date or individual impact cost is confirmed on this preview.</p>`)}));
document.querySelector('#content-action').addEventListener('click',()=>{contentDialog.close();document.querySelector('#appeal').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});
const policies={privacy:['PRIVACY','Your information matters.','<p>This preview has no payment collection, donor account, newsletter submission or beneficiary application form. Donation selections remain in this page’s memory and are not saved as pledges.</p><p>The hosting service may process technical access information. Google Fonts is used to load typography. AfriRise’s complete privacy notice, legal identity, contact channel, retention rules and rights-request process must be published before personal-data forms launch.</p>'],donations:['DONATION INFORMATION','Clarity before you give.','<p>The founding appeal goal is $500,000 USD. No collected amount has been verified for publication, and no funds can be collected through this preview.</p><p>Before checkout opens, AfriRise will publish its verified receiving entity and payment provider, approved campaign scope and budget, donor restrictions, recurring cancellation process, and rules for refunds, underfunding, excess funds and reallocations.</p><p>No claim of tax deductibility is made.</p>'],contact:['CONTACT & ENQUIRIES','Let’s build the next chapter.','<p>AfriRise’s official contact address and enquiry channel have not yet been supplied. A working contact route will be published here before the donor launch.</p><p>No message has been sent and no personal information is collected on this preview.</p>']};
document.querySelectorAll('[data-policy]').forEach(b=>b.addEventListener('click',()=>{const p=policies[b.dataset.policy];showContent(...p,false)}));
document.querySelectorAll('[data-involve]').forEach(b=>b.addEventListener('click',()=>showContent('GET INVOLVED',b.dataset.involve==='partner'?'Build possibility with us.':'Your experience can open doors.',`<p>${b.dataset.involve==='partner'?'We welcome conversations about programme delivery, equipment, mentoring and institutional support.':'Future opportunities may include technical delivery, education, mentoring and programme operations.'}</p><p>Partnership and volunteer enquiries will open when AfriRise’s official contact channel and participation process are published. This preview does not submit an application.</p>`,false)));
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';setTimeout(()=>el.style.display='none',5000)}
document.querySelector('#share-button').addEventListener('click',async()=>{const url=location.origin+location.pathname;try{if(navigator.share){await navigator.share({title:'AfriRise — A future worth rising for',text:'Explore AfriRise’s founding appeal for learning, livelihoods and community wellbeing.',url})}else{await navigator.clipboard.writeText(url);toast('Link copied. This review site currently has private access.')}}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable in this browser. You can copy the address from your browser.')}});
